def strategy(history, rng):
    rounds = len(history)
    if rounds == 0:
        return 'C'

    my_score = 0
    opp_score = 0
    my_defects = 0
    opp_defects = 0
    last_my, last_opp = history[-1]

    for my, opp in history:
        if my == 'C' and opp == 'C':
            my_score += 3
            opp_score += 3
        elif my == 'C' and opp == 'D':
            opp_score += 5
        elif my == 'D' and opp == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1
        if my == 'D':
            my_defects += 1
        if opp == 'D':
            opp_defects += 1

    if rounds < 5:
        return 'C'

    opp_defect_rate = opp_defects / rounds

    recent = history[-10:] if rounds >= 10 else history
    recent_opp_defects = sum(1 for _, o in recent if o == 'D')
    recent_opp_rate = recent_opp_defects / len(recent)

    # Identify likely always-defect or mostly-defect opponents
    if opp_defect_rate > 0.9:
        return 'D'

    # Forgiving tit-for-tat with noise resistance
    if recent_opp_rate > 0.6:
        return 'D'

    if last_opp == 'D' and last_my == 'C':
        # They just defected. Defect occasionally but mostly retaliate once.
        if recent_opp_rate > 0.3:
            return 'D'
        else:
            return 'D'

    if last_opp == 'D' and last_my == 'D':
        # Both defected; try to restore cooperation
        return 'C'

    if last_opp == 'C' and last_my == 'D':
        return 'C'

    # Cooperate, but occasionally probe if opponent seems too cooperative
    if opp_defect_rate < 0.05 and rounds > 20:
        if rng.random() < 0.02:
            return 'D'

    return 'C'
